content:
Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Customer",
      "description": "person requesting and receiving relocation services",
      "attributes": [
        "Inventory List"
      ]
    },
    {
      "name": "Inventory List",
      "description": "detailed list of the customer’s items to be moved"
    },
    {
      "name": "Moving Quote",
      "description": "estimated cost for the relocation"
    },
    {
      "name": "Relocation",
      "description": "planned moving service for the customer",
      "attributes": [
        "Moving Date",
        "Pick Up Location",
        "Delivery Location"
      ]
    },
    {
      "name": "Moving Date",
      "description": "scheduled day for the move"
    },
    {
      "name": "Pick Up Location",
      "description": "place where items are collected"
    },
    {
      "name": "Delivery Location",
      "description": "place where items are delivered"
    },
    {
      "name": "Move Coordinator",
      "description": "team member managing and overseeing the relocation process"
    },
    {
      "name": "Moving Crew",
      "description": "team performing the physical moving tasks",
      "attributes": [
        "Packing Specialist",
        "Driver",
        "Crew Supervisor"
      ]
    },
    {
      "name": "Packing Specialist",
      "description": "crew member responsible for packing and labeling boxes"
    },
    {
      "name": "Driver",
      "description": "crew member responsible for transport and route handling"
    },
    {
      "name": "Crew Supervisor",
      "description": "crew member overseeing on site moving operations"
    },
    {
      "name": "Box",
      "description": "packed container holding customer items",
      "attributes": [
        "Label"
      ]
    },
    {
      "name": "Label",
      "description": "marking used to identify a box and its destination"
    },
    {
      "name": "Delivery",
      "description": "transport stage of the relocation",
      "attributes": [
        "Route",
        "Delivery Status"
      ]
    },
    {
      "name": "Route",
      "description": "planned path from pick up to delivery",
      "attributes": [
        "Pick Up Location",
        "Delivery Location"
      ]
    },
    {
      "name": "Delivery Status",
      "description": "progress info about the current delivery"
    },
    {
      "name": "Delivery Confirmation",
      "description": "acknowledgment that delivery is complete"
    },
    {
      "name": "Relocation Report",
      "description": "summary of the relocation created after completion"
    }
  ]
}
```
